arguments.command:
# These look like data symbols ($d) - likely in a data section but near code.
# Let me check what's around those addresses using objdump or nm
DBGFILE="/tmp/symbols/try1.dbg"

# Find nearest symbols
nm -C "$DBGFILE" 2>/dev/null | awk -v a1=0x2f4b20 -v a2=0x2f4c84 '
  { addr = strtonum("0x"$1) }
  addr <= strtonum(a1) { prev1 = $0; paddr1 = addr }
  addr > strtonum(a1) && !found1 { print "0x2f4b20 nearest before: " prev1; print "0x2f4b20 nearest after:  " $0; found1=1 }
  addr <= strtonum(a2) { prev2 = $0; paddr2 = addr }
  addr > strtonum(a2) && !found2 { print "0x2f4c84 nearest before: " prev2; print "0x2f4c84 nearest after:  " $0; found2=1 }
  found1 && found2 { exit }
' 2>/dev/null || echo "nm parsing failed, trying readelf..."

# Alternative: use readelf --syms and filter
readelf -Ws "$DBGFILE" 2>/dev/null | grep -i "FUNC" | awk '{
  addr = strtonum("0x"$2)
  size = strtonum("0x"$3) + 0
  if (addr > 0) printf "%s %d %s\n", $2, size, $8
}' | sort | awk -v t1="2f4b20" -v t2="2f4c84" '
  BEGIN { a1 = strtonum("0x"t1); a2 = strtonum("0x"t2) }
  { addr = strtonum("0x"$1); size=$2+0 }
  addr <= a1 && (addr+size) > a1 { print "0x"t1" is in: "$3" (at 0x"$1", size "$2")" }
  addr <= a2 && (addr+size) > a2 { print "0x"t2" is in: "$3" (at 0x"$1", size "$2")" }
' 2>/dev/null | head -10

